from typing import TypedDict, Annotated, List, Dict, Any
import operator

class IncidentState(TypedDict):
    # Raw log string that triggered the orchestrator
    raw_log: str
    
    # Root cause output from Investigation Agent
    root_cause: str
    
    # Proposed patch generated by Development Agent
    proposed_patch: str
    
    # Validation results from Locust test
    test_results: Dict[str, Any]
    
    # Counter to avoid infinite loops when fixes keep failing
    retry_count: int
    
    # Chronological message history across all nodes
    history: Annotated[List[str], operator.add]